sql.where:
a.deleted = 0

    AND a.status = #{status}


    AND a.category_id = #{categoryId}


    AND EXISTS (SELECT 1 FROM article_tag at4 WHERE at4.article_id = a.id AND at4.tag_id = #{tagId})


    AND a.author_id = #{authorId}


    AND (a.title LIKE CONCAT('%', #{keyword}, '%')
         OR a.summary LIKE CONCAT('%', #{keyword}, '%')
         OR a.content LIKE CONCAT('%', #{keyword}, '%'))


    AND YEAR(a.create_time) = #{year}


    AND MONTH(a.create_time) = #{month}

mapper.select:
SELECT at.article_id, t.id AS tag_id, t.name AS tag_name, (SELECT COUNT(*) FROM article_tag x INNER JOIN article a2 ON a2.id = x.article_id AND a2.status = 1 AND a2.deleted = 0 WHERE x.tag_id = t.id) AS article_count FROM article_tag at INNER JOIN tag t ON t.id = at.tag_id WHERE at.article_id IN
#{articleId}
ORDER BY at.article_id ASC, t.id ASC
